{
  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    dist_edges = case['distances']

    # Build edges with mutual reachability, canonicalise endpoints
    edges = []
    for u, v, d in dist_edges:
        if u < v:
            u1, v1 = u, v
        else:
            u1, v1 = v, u
        weight = max(core_dist[u], core_dist[v], d)
        edges.append((weight, u1, v1))

    # Sort deterministically: weight, then u, then v
    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    # Union-Find
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    for weight, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == len(nodes) - 1:
                break

    # If the graph is disconnected, raise an error (should not happen in valid inputs)
    if len(mst_edges) != len(nodes) - 1:
        raise ValueError('Disconnected graph')

    return {'mst_edges': mst_edges, 'total_weight': total_weight}"
}
